<?php require 'config/db.php';require 'includes/functions.php';require_role('hospital');$uid=user()['id'];$h=$conn->query("SELECT * FROM hospitals WHERE user_id=$uid LIMIT 1")->fetch_assoc();$hid=(int)($h['id']??0);$active=(int)$conn->query("SELECT COUNT(*) c FROM blood_requests WHERE hospital_id=$hid AND status NOT IN ('completed','cancelled')")->fetch_assoc()['c'];$stock=$conn->query("SELECT * FROM blood_stock WHERE hospital_id=$hid ORDER BY FIELD(blood_group,'O-','O+','A-','A+','B-','B+','AB-','AB+')");$reqs=$conn->query("SELECT * FROM blood_requests WHERE hospital_id=$hid ORDER BY created_at DESC LIMIT 8");$pageTitle='Hospital Dashboard';include 'includes/header.php';?>
<section class="dashboard"><div class="container"><div class="dashboard-head"><div><span class="kicker">Hospital operations</span><h1><?=e($h['name']??user()['name'])?></h1><p>Emergency demand, blood stock and active donor coordination.</p></div><a class="btn btn-primary" href="request-blood.php">Create verified request</a></div><div class="metric-grid"><div class="metric"><div class="icon"><i class="fa-solid fa-bolt"></i></div><strong><?=$active?></strong><span>Active cases</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-droplet"></i></div><strong><?=$stock->num_rows?></strong><span>Tracked groups</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-shield-halved"></i></div><strong>Verified</strong><span>Hospital status</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-qrcode"></i></div><strong>QR</strong><span>Completion flow</span></div></div><div class="dash-grid"><div class="panel"><h3>Hospital emergency requests</h3><div class="table-wrap"><table class="table"><tr><th>Patient</th><th>Blood</th><th>Units</th><th>Status</th><th></th></tr><?php while($r=$reqs->fetch_assoc()):?><tr><td><?=e($r['patient_name'])?></td><td><b><?=e($r['blood_group'])?></b></td><td><?=$r['units']?></td><td><?=e(status_label($r['status']))?></td><td><a class="btn btn-sm btn-ghost" href="request-view.php?id=<?=$r['id']?>">Manage</a></td></tr><?php endwhile;?></table></div></div><div class="panel"><h3>Blood stock monitor</h3><div class="blood-stock"><?php $stock->data_seek(0);while($s=$stock->fetch_assoc()):?><div class="stock <?=$s['units']<$s['min_threshold']?'low':''?>"><b><?=e($s['blood_group'])?></b><span><?=$s['units']?> units</span></div><?php endwhile;?></div><p class="form-note" style="margin-top:15px">Low-stock groups are highlighted automatically.</p></div></div></div></section><?php include 'includes/footer.php';?>
